def top_word(sentence):
    freq = {}
    for w in sentence.lower().split():
        if w in freq:
            freq[w] += 1
        else:
            freq[w] = 1
    winner = ""
    highest = 0
    for w, n in freq.items():
        if n > highest:
            winner = w
            highest = n
    return winner

